import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.C9_66ieh.js";const s="/TrueDeck/screenshot.png",g=JSON.parse('{"title":"Guide","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1785285552000}'),n={name:"index.md"};function d(i,t,l,c,p,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h1><p>Day-to-day use of TrueDeck Studio. Install from <strong><a href="https://github.com/WutIsHummus/TrueDeck/releases" target="_blank" rel="noreferrer">Releases</a></strong> (do not clone the repo just to run the app). For first-time setup detail, see <a href="/TrueDeck/getting-started">Getting started</a>.</p><h2 id="studio-ui-layout" tabindex="-1">Studio UI layout <a class="header-anchor" href="#studio-ui-layout" aria-label="Permalink to &quot;Studio UI layout&quot;">​</a></h2><p class="studio-shot"><img src="'+s+'" alt="TrueDeck multi-pane studio"></p><div class="layout-wire"><div class="lw-title">Title bar · Project · board · settings · window controls</div><div class="lw-panes"><div class="lw-pane"><div class="lw-tabs">Group A tabs</div><div class="lw-term">Terminal (active agent)</div></div><div class="lw-pane"><div class="lw-tabs">Group B tabs</div><div class="lw-term">Terminal (or stacked below)</div></div></div><div class="lw-status">Status · shortcuts</div></div><table tabindex="0"><thead><tr><th>Control</th><th>Action</th></tr></thead><tbody><tr><td><strong>Project ▾</strong></td><td>Recent projects and Open Folder (<strong>Ctrl+O</strong>)</td></tr><tr><td><strong>Board</strong></td><td>Task board (<strong>Ctrl+B</strong>)</td></tr><tr><td><strong>⚙</strong></td><td>Settings (<strong>Ctrl+S</strong>)</td></tr><tr><td><strong>?</strong></td><td>Help / replay onboarding</td></tr><tr><td><strong>+</strong> / <strong>Ctrl+T</strong></td><td>Agent palette</td></tr><tr><td><strong>Drag a tab</strong></td><td>Left / Right / Top / Bottom to split; center joins a group</td></tr></tbody></table><p>Almost all of the window is terminal chrome. TrueDeck is not a three-column IDE.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>A <strong>project</strong> is a folder TrueDeck tracks in app data (<code>projects.json</code>):</p><table tabindex="0"><thead><tr><th>Field</th><th>Role</th></tr></thead><tbody><tr><td><code>name</code></td><td>Display name (usually folder basename)</td></tr><tr><td><code>root</code></td><td>Absolute path</td></tr><tr><td><code>onOpenCommands</code></td><td>Shell commands run as panes when you open the project</td></tr><tr><td><code>defaultAgents</code></td><td>Preferred agent ids for that project</td></tr><tr><td><code>lastOpened</code></td><td>Recents ordering</td></tr></tbody></table><h3 id="open-switch" tabindex="-1">Open / switch <a class="header-anchor" href="#open-switch" aria-label="Permalink to &quot;Open / switch&quot;">​</a></h3><ul><li><strong>Ctrl+O</strong> - native folder picker (adds project if new)</li><li>Project menu - switch among recents</li></ul><h3 id="on-open-commands" tabindex="-1">On-open commands <a class="header-anchor" href="#on-open-commands" aria-label="Permalink to &quot;On-open commands&quot;">​</a></h3><p>Settings → <strong>Project</strong> → On-open commands. Example: <code>rojo serve</code> as a shell pane when you open a Roblox repo. These are <strong>not</strong> agent presets; they spawn as command sessions and can be restored with the session layout.</p><h3 id="reopen-last-project" tabindex="-1">Reopen last project <a class="header-anchor" href="#reopen-last-project" aria-label="Permalink to &quot;Reopen last project&quot;">​</a></h3><p>Default: <strong>on</strong>. On launch, TrueDeck restores the last project and respawns saved tabs (capped). See <a href="#session-restore">Session restore</a>.</p><h2 id="tabs-and-sessions" tabindex="-1">Tabs and sessions <a class="header-anchor" href="#tabs-and-sessions" aria-label="Permalink to &quot;Tabs and sessions&quot;">​</a></h2><p>Each agent or command pane is a <strong>session</strong> (PTY):</p><ul><li>Running sessions stream into an xterm instance</li><li><strong>Ctrl+W</strong> closes the active tab</li><li><strong>Ctrl+Tab</strong> / <strong>Ctrl+Shift+Tab</strong> cycles tabs inside the focused pane group</li><li><strong>Ctrl+1-9</strong> jumps to tab index 1-9</li><li><strong>Ctrl+N</strong> opens a plain <strong>Shell</strong> tab in the project root</li></ul><p>Sessions show agent name, color, and exit status when the process ends.</p><h2 id="pane-groups-splits" tabindex="-1">Pane groups (splits) <a class="header-anchor" href="#pane-groups-splits" aria-label="Permalink to &quot;Pane groups (splits)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Split vertical (side-by-side)</td><td><strong>Ctrl+D</strong></td></tr><tr><td>Split horizontal (top/bottom)</td><td><strong>Ctrl+X</strong></td></tr><tr><td>Merge all groups to one pane</td><td><strong>Ctrl+Alt+D</strong> (or <strong>Ctrl+Alt+X</strong>)</td></tr></tbody></table><p>You need at least two tabs (or two leaves) to split. Hard cap: <strong>16</strong> panes. Soft warning around 12 panes.</p><p>Drag-and-drop zones:</p><ul><li><strong>Left / Right / Top / Bottom</strong> - create or target a split edge</li><li><strong>Center</strong> - move the tab into that group</li></ul><p>Selecting a tab focuses its group without collapsing the other pane.</p><h2 id="task-board" tabindex="-1">Task board <a class="header-anchor" href="#task-board" aria-label="Permalink to &quot;Task board&quot;">​</a></h2><p><strong>Ctrl+B</strong> toggles the board. Create tasks, set status, assign an agent, and dispatch. Full detail: <a href="/TrueDeck/task-board">Task board</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><strong>Ctrl+S</strong> opens Settings. Tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Contents</th></tr></thead><tbody><tr><td><strong>General</strong></td><td>Theme, memory abstraction notes, palace path, inject-on-start</td></tr><tr><td><strong>MCP</strong></td><td>Unified MCP list, add/remove user servers, sync/export</td></tr><tr><td><strong>Terminal</strong></td><td>Font size, layout mode, agent frame TUI, PTY engine label, shortcut hint</td></tr><tr><td><strong>Project</strong></td><td>Current project name/path, on-open commands</td></tr><tr><td><strong>Agents</strong></td><td>Agent list / reset presets</td></tr><tr><td><strong>About</strong></td><td>Version, update check, replay onboarding</td></tr></tbody></table><p>See <a href="/TrueDeck/configuration">Configuration</a>.</p><h2 id="session-restore" tabindex="-1">Session restore <a class="header-anchor" href="#session-restore" aria-label="Permalink to &quot;Session restore&quot;">​</a></h2><p>On quit, TrueDeck saves <code>session-layout.json</code> (tabs, multi-pane tree, active project). On next launch it respawns those PTYs (max 16 tabs).</p><h2 id="memory-automatic" tabindex="-1">Memory (automatic) <a class="header-anchor" href="#memory-automatic" aria-label="Permalink to &quot;Memory (automatic)&quot;">​</a></h2><p>You do not manage a memory badge. On project open and agent spawn, TrueDeck ensures <code>.memory/</code>, refreshes <code>.truedeck/auto-context.md</code>, injects env paths, and warms MemPalace when configured. Details: <a href="/TrueDeck/memory-providers">Memory providers</a>.</p><h2 id="pty-backend" tabindex="-1">PTY backend <a class="header-anchor" href="#pty-backend" aria-label="Permalink to &quot;PTY backend&quot;">​</a></h2><p><strong>Rust (<code>truedeck-backend</code>) is the main backend</strong> for sessions. <code>node-pty</code> is only an emergency fallback if the Rust binary is missing or fails to start.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Open a project before <strong>Ctrl+T</strong> / <strong>Ctrl+N</strong> / board dispatch</li><li>Prefer fewer simultaneous agent panes for machine load</li><li>Install CLIs system-wide so resolve finds them on <code>PATH</code></li><li>On Windows, use <code>cursor-agent</code> install, not Cursor IDE shortcuts</li><li>Full shortcut list: <a href="/TrueDeck/keyboard-shortcuts">Keyboard shortcuts</a></li></ul>',40)])])}const m=e(n,[["render",d]]);export{g as __pageData,m as default};
